INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-26', 'es', 'LAIKA 64 3.6.1: avatares premium y sala con jugadores listos', 'Avatares premium animados con brillo rosa y fijados arriba en la lista: pídelo en Perfil > Avatar personalizado. En las salas pulsa Y para estar listo: la partida empieza cuando todos lo están. Juego en línea más estable. Actualiza desde LAIKA.'),
 ('2026-11-26', 'en', 'LAIKA 64 3.6.1: premium avatars and ready players in rooms', 'Animated premium avatars with a pink glow, pinned at the top of the list: ask in Profile > Custom avatar. In rooms press Y when ready: the game starts once everyone is. More stable online play. Update from LAIKA.'),
 ('2026-11-26', 'pt', 'LAIKA 64 3.6.1: avatares premium e jogadores prontos na sala', 'Avatares premium animados com brilho rosa, fixados no topo da lista: peça em Perfil > Avatar personalizado. Nas salas aperte Y quando estiver pronto: a partida começa quando todos estão. Jogo online mais estável. Atualize pelo LAIKA.'),
 ('2026-11-26', 'fr', 'LAIKA 64 3.6.1 : avatars premium et joueurs prêts', 'Avatars premium animés avec une lueur rose, épinglés en haut de la liste : demande-le dans Profil > Avatar personnalisé. Dans les salles, appuie sur Y quand tu es prêt : la partie démarre quand tous le sont. Jeu en ligne plus stable. Mets à jour depuis LAIKA.'),
 ('2026-11-26', 'de', 'LAIKA 64 3.6.1: Premium-Avatare und Bereit-Status', 'Animierte Premium-Avatare mit rosa Leuchten, oben in der Liste angeheftet: bestelle ihn unter Profil > Eigener Avatar. In Räumen drückst du Y, wenn du bereit bist: das Spiel startet, wenn alle es sind. Stabileres Online-Spiel. Aktualisiere in LAIKA.'),
 ('2026-11-26', 'it', 'LAIKA 64 3.6.1: avatar premium e giocatori pronti', 'Avatar premium animati con bagliore rosa, fissati in cima alla lista: richiedilo in Profilo > Avatar personalizzato. Nelle stanze premi Y quando sei pronto: la partita inizia quando lo sono tutti. Gioco online più stabile. Aggiorna da LAIKA.'),
 ('2026-11-26', 'ru', 'LAIKA 64 3.6.1: премиум-аватары и готовность в комнатах', 'Анимированные премиум-аватары с розовым свечением, закреплённые вверху списка: закажи в Профиль > Свой аватар. В комнатах нажми Y, когда готов: игра начнётся, когда готовы все. Стабильнее онлайн-игра. Обновись из LAIKA.');
